(function(){
  if(!window.FTR_EXTRA || typeof window.startApp !== "function") return;
  const original = window.startApp;
  window.startApp = function(S, G){
    for(const s of S){ const x = window.FTR_EXTRA[s.id]; if(x) for(const [q,a,d] of x) s.cards.push({q, a, d}); }
    for(const ns of (window.FTR_EXTRA_SECTIONS || [])){
      if(S.some(s => s.id === ns.id)) continue;
      S.push({ id:ns.id, tag:ns.tag, title:ns.title, lead:ns.lead, blocks:ns.blocks, cards: ns.cards.map(([q,a,d]) => ({q, a, d})) });
    }
    return original(S, G);
  };
})();
